        bus.write_long(TEST_SP + 8, event_ptr);

        disp.dispatch_dialog(true, 0x180, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();

        (
            bus.read_byte(TEST_SP + 12),
            bus.read_long(dialog_out_ptr),
            bus.read_word(item_hit_ptr),
            cpu.read_reg(Register::A7),
        )
